-- Typed projections and stage mappings; no authority ledger. / 类型化投影和环节映射，非权威账本。
CREATE TABLE projection_registry (enterprise_id uuid NOT NULL, id uuid NOT NULL, kind text NOT NULL CHECK(kind IN ('product_revision','demand_supply_bucket','trade_line','stock_position_movement','resource_commitment','supplier_delivery','production_order','logistics_line','finance_entry_projection','customer_lifecycle_snapshot','store_asset_observation','responsibility_capacity')), schema_version integer NOT NULL CHECK(schema_version>0), source_record_id uuid NOT NULL, fact_kind text NOT NULL CHECK(fact_kind IN ('source_actual','constructed_actual','budget','forecast','scenario_plan')), business_time timestamptz NOT NULL, recorded_at timestamptz NOT NULL, PRIMARY KEY(enterprise_id,id), UNIQUE(enterprise_id,id,kind), FOREIGN KEY(enterprise_id,source_record_id) REFERENCES source_record(enterprise_id,id));
CREATE TRIGGER projection_mode_check BEFORE INSERT OR UPDATE ON projection_registry FOR EACH ROW EXECUTE FUNCTION reject_constructed_enterprise();
CREATE TABLE product_revision (enterprise_id uuid NOT NULL, id uuid NOT NULL, kind text NOT NULL DEFAULT 'product_revision' CHECK(kind='product_revision'), sku_id text NOT NULL, pack_version integer NOT NULL, bom_version text NOT NULL, effective_from date NOT NULL, effective_to date, approval_state text NOT NULL CHECK(approval_state IN ('draft','review','approved')), replacement_sku text, PRIMARY KEY(enterprise_id,id), FOREIGN KEY(enterprise_id,id,kind) REFERENCES projection_registry(enterprise_id,id,kind));
CREATE TABLE demand_supply_bucket (enterprise_id uuid NOT NULL, id uuid NOT NULL, kind text NOT NULL DEFAULT 'demand_supply_bucket' CHECK(kind='demand_supply_bucket'), sku_id text NOT NULL, location_id text NOT NULL, week_start date NOT NULL, forecast_version text NOT NULL, demand_cases bigint NOT NULL CHECK(demand_cases>=0), supply_cases bigint NOT NULL CHECK(supply_cases>=0), consumed_order_cases bigint NOT NULL CHECK(consumed_order_cases>=0 AND consumed_order_cases<=demand_cases), supply_type text NOT NULL, available_on date NOT NULL, commitment_state text NOT NULL, PRIMARY KEY(enterprise_id,id), FOREIGN KEY(enterprise_id,id,kind) REFERENCES projection_registry(enterprise_id,id,kind));
CREATE TABLE trade_line (enterprise_id uuid NOT NULL, id uuid NOT NULL, kind text NOT NULL DEFAULT 'trade_line' CHECK(kind='trade_line'), document_code text NOT NULL, line_no integer NOT NULL, customer_code text NOT NULL, store_code text, primary_channel text NOT NULL, outlet_format text NOT NULL, ka_tier text NOT NULL, touchpoint text NOT NULL, sell_kind text NOT NULL CHECK(sell_kind IN ('sell_in','sell_out')), quantity numeric(22,6) NOT NULL, unit_code text NOT NULL, net_amount numeric(22,6) NOT NULL, tax_amount numeric(22,6) NOT NULL, currency text NOT NULL, recognition_date date NOT NULL, PRIMARY KEY(enterprise_id,id), FOREIGN KEY(enterprise_id,id,kind) REFERENCES projection_registry(enterprise_id,id,kind));
CREATE TABLE stock_position_movement (enterprise_id uuid NOT NULL, id uuid NOT NULL, kind text NOT NULL DEFAULT 'stock_position_movement' CHECK(kind='stock_position_movement'), sku_id text NOT NULL, pack_version integer NOT NULL, lot_code text NOT NULL, owner_code text NOT NULL, site_code text NOT NULL, quality_state text NOT NULL CHECK(quality_state IN ('released','inspection','held')), opening_qty numeric(22,6) NOT NULL, receipts_qty numeric(22,6) NOT NULL, issues_qty numeric(22,6) NOT NULL, adjustment_qty numeric(22,6) NOT NULL, closing_qty numeric(22,6) NOT NULL, unit_code text NOT NULL, conversion_version text NOT NULL, cutoff date NOT NULL, CHECK(opening_qty+receipts_qty-issues_qty+adjustment_qty=closing_qty), PRIMARY KEY(enterprise_id,id), FOREIGN KEY(enterprise_id,id,kind) REFERENCES projection_registry(enterprise_id,id,kind));
CREATE TABLE resource_commitment (enterprise_id uuid NOT NULL, id uuid NOT NULL, kind text NOT NULL DEFAULT 'resource_commitment' CHECK(kind='resource_commitment'), resource_code text NOT NULL, bucket_start timestamptz NOT NULL, bucket_end timestamptz NOT NULL CHECK(bucket_end>bucket_start), unit_code text NOT NULL, capacity numeric(22,6) NOT NULL CHECK(capacity>=0), reserved numeric(22,6) NOT NULL CHECK(reserved>=0 AND reserved<=capacity), plan_code text NOT NULL, source_reservation_ref text, state text NOT NULL CHECK(state IN ('planned','reserved','unknown','released')), version integer NOT NULL CHECK(version>0), PRIMARY KEY(enterprise_id,id), FOREIGN KEY(enterprise_id,id,kind) REFERENCES projection_registry(enterprise_id,id,kind));
CREATE TABLE supplier_delivery (enterprise_id uuid NOT NULL, id uuid NOT NULL, kind text NOT NULL DEFAULT 'supplier_delivery' CHECK(kind='supplier_delivery'), supplier_code text NOT NULL, qualification_version text NOT NULL, qualification_until date NOT NULL, material_code text NOT NULL, po_code text NOT NULL, promised_on date NOT NULL, arrived_on date, expected_qty numeric(22,6) NOT NULL, actual_qty numeric(22,6), unit_code text NOT NULL, inspection_ref text, capa_ref text, PRIMARY KEY(enterprise_id,id), FOREIGN KEY(enterprise_id,id,kind) REFERENCES projection_registry(enterprise_id,id,kind));
CREATE TABLE production_order (enterprise_id uuid NOT NULL, id uuid NOT NULL, kind text NOT NULL DEFAULT 'production_order' CHECK(kind='production_order'), order_code text NOT NULL, line_code text NOT NULL, copacker_code text, sku_id text NOT NULL, process_version text NOT NULL, bom_version text NOT NULL, shift_date date NOT NULL, scheduled_hours numeric(12,2) NOT NULL, maintenance_hours numeric(12,2) NOT NULL, cleaning_hours numeric(12,2) NOT NULL, input_cases bigint NOT NULL, good_output_cases bigint NOT NULL CHECK(good_output_cases>=0 AND good_output_cases<=input_cases), fact_state text NOT NULL CHECK(fact_state IN ('planned','actual')), CHECK(maintenance_hours+cleaning_hours<=scheduled_hours), PRIMARY KEY(enterprise_id,id), FOREIGN KEY(enterprise_id,id,kind) REFERENCES projection_registry(enterprise_id,id,kind));
CREATE TABLE logistics_line (enterprise_id uuid NOT NULL, id uuid NOT NULL, kind text NOT NULL DEFAULT 'logistics_line' CHECK(kind='logistics_line'), transfer_code text NOT NULL, from_site text NOT NULL, to_site text NOT NULL, owner_code text NOT NULL, legal_entity_code text NOT NULL, sku_id text NOT NULL, lot_code text NOT NULL, shipped_cases bigint NOT NULL CHECK(shipped_cases>=0), received_cases bigint NOT NULL CHECK(received_cases>=0 AND received_cases<=shipped_cases), stage text NOT NULL CHECK(stage IN ('request','shipped','received')), required_arrival timestamptz NOT NULL, source_document_code text NOT NULL, PRIMARY KEY(enterprise_id,id), FOREIGN KEY(enterprise_id,id,kind) REFERENCES projection_registry(enterprise_id,id,kind));
CREATE TABLE finance_entry_projection (enterprise_id uuid NOT NULL, id uuid NOT NULL, kind text NOT NULL DEFAULT 'finance_entry_projection' CHECK(kind='finance_entry_projection'), document_code text NOT NULL, legal_entity_code text NOT NULL, account_code text NOT NULL, customer_code text, currency text NOT NULL, fx_version text NOT NULL, amount numeric(22,6) NOT NULL, entry_kind text NOT NULL, recognized_on date NOT NULL, due_on date, allocated_on date, intercompany boolean NOT NULL DEFAULT false, PRIMARY KEY(enterprise_id,id), FOREIGN KEY(enterprise_id,id,kind) REFERENCES projection_registry(enterprise_id,id,kind));
CREATE TABLE customer_lifecycle_snapshot (enterprise_id uuid NOT NULL, id uuid NOT NULL, kind text NOT NULL DEFAULT 'customer_lifecycle_snapshot' CHECK(kind='customer_lifecycle_snapshot'), party_code text NOT NULL, party_type text NOT NULL CHECK(party_type IN ('B2B','B2C')), parent_code text, snapshot_on date NOT NULL, cohort_code text NOT NULL, segment_rule text NOT NULL, cohort_size integer NOT NULL CHECK(cohort_size>=0), repeat_count integer NOT NULL CHECK(repeat_count>=0 AND repeat_count<=cohort_size), marketing_consent boolean NOT NULL, unresolved_service_code text, PRIMARY KEY(enterprise_id,id), FOREIGN KEY(enterprise_id,id,kind) REFERENCES projection_registry(enterprise_id,id,kind));
CREATE TABLE store_asset_observation (enterprise_id uuid NOT NULL, id uuid NOT NULL, kind text NOT NULL DEFAULT 'store_asset_observation' CHECK(kind='store_asset_observation'), store_code text NOT NULL, asset_code text NOT NULL, shelf_code text NOT NULL, floorplan_version text NOT NULL, sku_id text NOT NULL, window_start timestamptz NOT NULL, window_end timestamptz NOT NULL CHECK(window_end>window_start), traffic_count integer NOT NULL CHECK(traffic_count>=0), dwell_seconds integer NOT NULL CHECK(dwell_seconds>=0), observed_minutes integer NOT NULL CHECK(observed_minutes>=0), stockout_minutes integer NOT NULL CHECK(stockout_minutes>=0 AND stockout_minutes<=observed_minutes), device_online boolean NOT NULL, temperature_c numeric(8,2), experiment_group text NOT NULL, PRIMARY KEY(enterprise_id,id), FOREIGN KEY(enterprise_id,id,kind) REFERENCES projection_registry(enterprise_id,id,kind));
CREATE TABLE responsibility_capacity (enterprise_id uuid NOT NULL, id uuid NOT NULL, kind text NOT NULL DEFAULT 'responsibility_capacity' CHECK(kind='responsibility_capacity'), org_code text NOT NULL, role_code text NOT NULL, assignment_code text NOT NULL, work_date date NOT NULL, scheduled_hours numeric(12,2) NOT NULL, available_hours numeric(12,2) NOT NULL CHECK(available_hours>=0 AND available_hours<=scheduled_hours), aggregate_cost numeric(22,6) NOT NULL, currency text NOT NULL, field_policy text NOT NULL, PRIMARY KEY(enterprise_id,id), FOREIGN KEY(enterprise_id,id,kind) REFERENCES projection_registry(enterprise_id,id,kind));
CREATE TABLE business_stage (domain_id text NOT NULL, stage_id text NOT NULL, ordinal integer NOT NULL CHECK(ordinal BETWEEN 0 AND 3), title jsonb NOT NULL, domain_title jsonb NOT NULL, owner_title jsonb NOT NULL, metric_ids text[] NOT NULL, projection_kind text NOT NULL, rule_ids text[] NOT NULL, read_tool text NOT NULL, action_capability text NOT NULL CHECK(action_capability IN ('read_only','proposal_only')), PRIMARY KEY(domain_id,stage_id), UNIQUE(domain_id,ordinal));
CREATE TABLE stage_projection (enterprise_id uuid NOT NULL, domain_id text NOT NULL, stage_id text NOT NULL, projection_id uuid NOT NULL, projection_kind text NOT NULL, PRIMARY KEY(enterprise_id,domain_id,stage_id,projection_id), FOREIGN KEY(domain_id,stage_id) REFERENCES business_stage(domain_id,stage_id), FOREIGN KEY(enterprise_id,projection_id,projection_kind) REFERENCES projection_registry(enterprise_id,id,kind));
-- Tenant policies also protect inherited projection sources. / 企业策略同时保护投影与源记录。
DO $$ DECLARE t text; BEGIN
 FOR t IN SELECT table_name FROM information_schema.columns WHERE table_schema='public' AND column_name='enterprise_id' LOOP
  EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t);
  EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY',t);
  EXECUTE format('CREATE POLICY enterprise_isolation ON %I USING (enterprise_id::text = current_setting(''app.enterprise_id'',true)) WITH CHECK (enterprise_id::text = current_setting(''app.enterprise_id'',true))',t);
 END LOOP;
END $$;
ALTER TABLE enterprise ENABLE ROW LEVEL SECURITY;
ALTER TABLE enterprise FORCE ROW LEVEL SECURITY;
CREATE POLICY enterprise_isolation ON enterprise USING(id::text=current_setting('app.enterprise_id',true));
GRANT USAGE ON SCHEMA public TO eb_app;
GRANT SELECT ON ALL TABLES IN SCHEMA public TO eb_app;
REVOKE ALL ON schema_migration FROM eb_app;
REVOKE UPDATE, DELETE ON audit_event FROM eb_app;
-- Evidence holds prevent accidental destructive source deletion. / 保全防止误删依据。
CREATE FUNCTION held_evidence_delete() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF EXISTS(SELECT 1 FROM evidence_hold WHERE enterprise_id=OLD.enterprise_id AND source_record_id=OLD.id AND released_at IS NULL) THEN RAISE EXCEPTION 'evidence_held'; END IF; RETURN OLD; END $$;
CREATE TRIGGER source_delete_hold BEFORE DELETE ON source_record FOR EACH ROW EXECUTE FUNCTION held_evidence_delete();
